// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    address owner = address(0xABCD);

    function setUp() public { 
        c = new DepositLog();
    }

    function testFuzz_property(address logger, bool status) public {

        bool ok;
        vm.prank(address(0));
        try c.setApprovedLogger(logger, status) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.approvedLoggers(logger) == status);
        } else {
            assertTrue(ok == false);
        }
    }
}
